<?php
$period=(string)($_GET['period']??'90');if(!in_array($period,['30','90','180','365','all'],true))$period='90';
$analyticsError=null;try{$stats=analytics_load(local_user_id(),$period);}catch(Throwable $e){error_log('[OS::JOB analytics] '.$e->getMessage());$analyticsError='Statistiques indisponibles : vérifiez la connexion à la base.';$stats=null;}
?>
<div class="page-head"><div><div class="eyebrow">PILOTAGE · ANALYTICS</div><h1>Statistiques<span class="accent">.</span></h1><p>Mesurez votre activité et vos résultats à partir des candidatures réellement envoyées.</p></div><a class="button button-light" href="<?=url('dashboard')?>">← Tableau de bord</a></div>
<?php if($analyticsError):?><div class="os-alert os-alert--danger" role="alert"><?=e($analyticsError)?></div><?php elseif($stats):?>
<nav class="an-periods" aria-label="Période d'analyse"><?php foreach(['30'=>'30 jours','90'=>'90 jours','180'=>'6 mois','365'=>'12 mois','all'=>'Tout'] as $key=>$label):?><a class="an-period <?= $period===$key?'an-period--active':'' ?>" href="<?=e(url('analytics').'&period='.$key)?>" <?= $period===$key?'aria-current="page"':'' ?>><?=e($label)?></a><?php endforeach;?></nav>
<?php if($stats['warnings']):?><div class="os-alert os-alert--warning">Données partiellement indisponibles : <?=e(implode(', ',$stats['warnings']))?>. Certains résultats peuvent être incomplets.</div><?php endif;?>
<div class="an-kpis">
 <div class="an-kpi"><span>Candidatures envoyées</span><strong><?= $stats['sent'] ?></strong><small>Date d'envoi renseignée</small></div>
 <div class="an-kpi"><span>Taux de réponse indicatif</span><strong><?=e(analytics_pct($stats['responded'],$stats['sent']))?></strong><small><?= $stats['responded'] ?> dossiers avec signal de réponse ou statut conclusif</small></div>
 <div class="an-kpi"><span>Accès à l'entretien</span><strong><?=e(analytics_pct($stats['interviewed'],$stats['sent']))?></strong><small><?= $stats['interviewed'] ?> candidatures avec entretien ou statut associé</small></div>
 <div class="an-kpi"><span>Issues positives</span><strong><?=e(analytics_pct($stats['positive'],$stats['sent']))?></strong><small><?= $stats['positive'] ?> propositions ou acceptations</small></div>
</div>
<div class="an-grid">
<section class="os-card"><h2>Envois par mois</h2><p class="an-muted">Regroupement selon la date d'envoi enregistrée.</p><?php if(!$stats['months']):?><p class="an-empty">Aucune candidature envoyée sur cette période.</p><?php else:$max=max(1,...array_values($stats['months']));foreach($stats['months'] as $month=>$count):?><div class="an-bar-row"><span><?=e($month)?></span><div class="an-track"><div style="width:<?=round(100*$count/$max)?>%"></div></div><strong><?= $count ?></strong></div><?php endforeach;endif;?></section>
<section class="os-card"><h2>Étapes des candidatures</h2><p class="an-muted">Statut actuel des dossiers envoyés durant la période.</p><?php if(!$stats['statuses']):?><p class="an-empty">Aucune donnée.</p><?php else:foreach($stats['statuses'] as $status=>$count):?><div class="an-detail"><span><?=e(app_statuses()[$status]??$status)?></span><strong><?= $count ?></strong></div><?php endforeach;endif;?><div class="an-detail an-detail--summary"><span>En attente (applied / waiting)</span><strong><?= $stats['waiting'] ?></strong></div><div class="an-detail"><span>Refusées</span><strong><?= $stats['rejected'] ?></strong></div></section>
<section class="os-card"><h2>Plateformes de candidature</h2><p class="an-muted">Origine déclarée dans le dossier de candidature.</p><?php if(!$stats['platforms']):?><p class="an-empty">Aucune donnée.</p><?php else:foreach($stats['platforms'] as $platform=>$count):?><div class="an-detail"><span><?=e($platform)?></span><strong><?= $count ?></strong></div><?php endforeach;endif;?></section>
<section class="os-card"><h2>Scores de compatibilité</h2><p class="an-muted">Offres créées durant la période, scores disponibles uniquement.</p><div class="an-score-grid"><div><span>Score initial moyen</span><strong><?= $stats['baseline_avg']===null?'—':e((string)$stats['baseline_avg']).' %' ?></strong></div><div><span>Score effectif moyen</span><strong><?= $stats['effective_avg']===null?'—':e((string)$stats['effective_avg']).' %' ?></strong></div></div><p class="an-muted"><?= $stats['scores_count'] ?> offre(s) notée(s) · <?= $stats['validated_scores'] ?> réévaluation(s) acceptée(s). Les propositions IA non validées sont exclues.</p></section>
</div>
<p class="an-note"><strong>Méthodologie.</strong> Les taux utilisent uniquement les candidatures avec une date d'envoi dans la période sélectionnée. Le taux de réponse est une estimation à partir des événements et statuts enregistrés : les emails sortants ne sont pas considérés comme des réponses, et certaines réponses non saisies peuvent manquer. Les entretiens sont dédupliqués par candidature et incluent les changements de statut vers « Entretien » consignés dans l’historique ; une saisie de test peut donc influer sur les résultats. Les brouillons IA ne comptent pas comme réponses. Les scores concernent les offres créées durant la période, et non nécessairement les candidatures envoyées. Sur un petit échantillon, les pourcentages sont peu représentatifs.</p>
<?php endif;?>
